<?php
require_once __DIR__.'/includes/db.php';$pdo=db();$albumId=max(0,(int)($_GET['album_id']??0));$album=null;$photos=[];if($albumId){$s=$pdo->prepare('SELECT * FROM albums WHERE id=?');$s->execute([$albumId]);$album=$s->fetch();if($album){$s=$pdo->prepare('SELECT * FROM photos WHERE album_id=? ORDER BY id DESC');$s->execute([$albumId]);$photos=$s->fetchAll();}}$albums=$pdo->query('SELECT a.*,COUNT(p.id) photo_count FROM albums a LEFT JOIN photos p ON p.album_id=a.id GROUP BY a.id ORDER BY a.album_date DESC')->fetchAll();$pageTitle=$album?h($album['title']):'Фотоальбомы';require __DIR__.'/includes/header.php';
?><section class="mx-auto max-w-7xl px-4 py-14"><p class="font-bold uppercase tracking-widest text-red-500">Моменты большого спорта</p><h1 class="mt-2 text-4xl font-black"><?=$album?h($album['title']):'Фотоальбомы'?></h1><?php if($album):?><a class="mt-5 inline-block text-red-400" href="gallery.php">← Все альбомы</a><?php if(!$photos):?><div class="panel mt-8 rounded-2xl p-8 text-gray-400">В альбоме пока нет фотографий. Следите за обновлениями.</div><?php else:?><div class="mt-8 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4"><?php foreach($photos as $i=>$photo):?><button class="photo-open group relative aspect-square overflow-hidden rounded-xl bg-neutral-800" data-src="<?=h($photo['path'])?>" data-caption="<?=h($photo['caption'])?>"><img class="h-full w-full object-cover transition group-hover:scale-105" src="<?=h($photo['path'])?>" alt="<?=h($photo['caption']?:'Фотография из альбома')?>" loading="lazy"><span class="absolute inset-0 grid place-items-center bg-black/0 text-3xl opacity-0 transition group-hover:bg-black/30 group-hover:opacity-100"><i class="fa-solid fa-magnifying-glass-plus"></i></span></button><?php endforeach;?></div><?php endif;?><?php else:?><p class="mt-3 text-gray-400">Фотографии с тренировок, соревнований и событий школы.</p><div class="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><?php foreach($albums as $a):?><a href="gallery.php?album_id=<?=$a['id']?>" class="panel group overflow-hidden rounded-2xl"><div class="relative grid aspect-[4/3] place-items-center bg-gradient-to-br from-neutral-800 to-red-950"><?php if($a['cover']):?><img src="<?=h($a['cover'])?>" alt="<?=h($a['title'])?>" class="h-full w-full object-cover"><?php else:?><i class="fa-solid fa-images text-6xl text-white/20"></i><?php endif;?><span class="absolute bottom-3 right-3 rounded-full bg-black/70 px-3 py-1 text-xs"><?=$a['photo_count']?> фото</span></div><div class="p-5"><p class="text-sm text-red-400"><?=h(date('d.m.Y',strtotime($a['album_date'])))?></p><h2 class="mt-2 text-xl font-bold group-hover:text-red-300"><?=h($a['title'])?></h2></div></a><?php endforeach;?></div><?php endif;?></section><div id="lightbox" class="fixed inset-0 z-50 hidden items-center justify-center bg-black/95 p-4" role="dialog" aria-modal="true" aria-label="Просмотр фотографии"><button id="lightClose" type="button" class="light-control absolute right-6 top-4 text-4xl" aria-label="Закрыть просмотр фотографии">×</button><button id="lightPrev" type="button" class="light-control absolute left-4 top-1/2 text-4xl" aria-label="Предыдущая фотография">‹</button><figure class="max-h-[90vh] max-w-[90vw] text-center"><img id="lightImage" class="mx-auto max-h-[80vh] max-w-full object-contain" alt=""><figcaption id="lightCaption" class="mt-3"></figcaption></figure><button id="lightNext" type="button" class="light-control absolute right-4 top-1/2 text-4xl" aria-label="Следующая фотография">›</button></div><script>
(()=>{
    const photos=[...document.querySelectorAll('.photo-open')], lb=document.getElementById('lightbox');
    const close=document.getElementById('lightClose'), prev=document.getElementById('lightPrev'), next=document.getElementById('lightNext');
    let pi=0, opener=null;
    function showPhoto(n){pi=(n+photos.length)%photos.length;const b=photos[pi];document.getElementById('lightImage').src=b.dataset.src;document.getElementById('lightImage').alt=b.dataset.caption||'Фотография';document.getElementById('lightCaption').textContent=b.dataset.caption}
    function openLight(i){opener=document.activeElement;showPhoto(i);lb.classList.remove('hidden');lb.classList.add('flex');close.focus()}
    function hideLight(){if(lb.classList.contains('hidden'))return;lb.classList.add('hidden');lb.classList.remove('flex');if(opener)opener.focus()}
    photos.forEach((b,i)=>b.addEventListener('click',()=>openLight(i)));
    close.addEventListener('click',hideLight);prev.addEventListener('click',()=>showPhoto(pi-1));next.addEventListener('click',()=>showPhoto(pi+1));
    lb.addEventListener('click',e=>{if(e.target===lb)hideLight()});
    document.addEventListener('keydown',e=>{if(lb.classList.contains('hidden'))return;if(e.key==='Escape'){e.preventDefault();hideLight()}else if(e.key==='ArrowRight'){e.preventDefault();showPhoto(pi+1)}else if(e.key==='ArrowLeft'){e.preventDefault();showPhoto(pi-1)}else if(e.key==='Tab'){const buttons=[close,prev,next],i=buttons.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();next.focus()}else if(!e.shiftKey&&(i===buttons.length-1||i<0)){e.preventDefault();close.focus()}}});
})();
</script><?php require __DIR__.'/includes/footer.php';
